      <input
        ref={ref}
        type="range"
        min={min}
        max={max}
        step={step}
        value={current}
        onChange={(e) => {
          const next = Number(e.target.value);
          if (!isControlled) setInner(next);
          onValueChange?.(next);
        }}
        {...props}
      />
    </div>
  );
