import * as React from "react";
import { cx } from "./cx";

export interface SelectOption {
  value: string;
  label: React.ReactNode;
}

export interface SelectProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> {
  options: SelectOption[];
  value?: string;
  defaultValue?: string;
  placeholder?: React.ReactNode;
  onValueChange?: (value: string) => void;
  disabled?: boolean;
}

/** Listbox pattern on a hairline trigger; the open menu overlays, it never pushes layout. */
export function Select({
  options,
  value,
  defaultValue,
  placeholder = "Select…",
  onValueChange,
  disabled,
  className,
  ...props
}: SelectProps) {
  const idBase = React.useId();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const [open, setOpen] = React.useState(false);
  const [inner, setInner] = React.useState(defaultValue);
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  const selectedIndex = options.findIndex((o) => o.value === current);
  const [activeIndex, setActiveIndex] = React.useState(Math.max(0, selectedIndex));

  const select = (next: string) => {
    if (!isControlled) setInner(next);
    onValueChange?.(next);
    setOpen(false);
    triggerRef.current?.focus();
  };

  React.useEffect(() => {
    if (!open) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!rootRef.current?.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("pointerdown", onPointerDown);
    return () => document.removeEventListener("pointerdown", onPointerDown);
  }, [open]);

  const onTriggerKeyDown = (e: React.KeyboardEvent) => {
    if (["ArrowDown", "ArrowUp", "Enter", " "].includes(e.key) && !open) {
      e.preventDefault();
      setActiveIndex(Math.max(0, selectedIndex));
      setOpen(true);
      return;
    }
    if (!open) return;
    if (e.key === "Escape") setOpen(false);
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(options.length - 1, i + 1));
    }
    if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(0, i - 1));
    }
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      const active = options[activeIndex];
      if (active) select(active.value);
    }
  };

  const selected = selectedIndex >= 0 ? options[selectedIndex] : undefined;

  return (
    <div ref={rootRef} className={cx("rs-select", className)} {...props}>
      <button
        ref={triggerRef}
        type="button"
        className="rs-dropdown"
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={`${idBase}-listbox`}
        disabled={disabled}
        onClick={() => setOpen((o) => !o)}
        onKeyDown={onTriggerKeyDown}
      >
        <span>{selected ? selected.label : placeholder}</span>
        <svg viewBox="0 0 16 16" width="16" height="16" fill="none" aria-hidden="true">
          <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </button>
      {open && (
        <div id={`${idBase}-listbox`} role="listbox" className="rs-menu" aria-activedescendant={`${idBase}-opt-${activeIndex}`}>
          {options.map((option, index) => (
            <button
              key={option.value}
              id={`${idBase}-opt-${index}`}
              type="button"
              role="option"
              aria-selected={option.value === current}
              className={cx(
                "rs-menu-item",
                (option.value === current || index === activeIndex) && "rs-menu-item-active",
              )}
              onPointerEnter={() => setActiveIndex(index)}
              onClick={() => select(option.value)}
            >
              {option.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Dropdown + menu — the menu overlays, it never pushes layout ── */
.rs-select{position:relative;display:inline-block;min-width:180px}
.rs-select .rs-menu{position:absolute;top:100%;left:0;right:0;z-index:50;margin-top:6px}
.rs-dropdown{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 12px;border:1px solid var(--divider);border-radius:var(--radius-sm);font-size:14px;color:var(--text);letter-spacing:-.01em}
button.rs-dropdown{cursor:pointer;font-family:inherit;background:none;width:100%}
.rs-menu{border:1px solid var(--divider);border-radius:var(--radius-sm);margin-top:6px;overflow:hidden;background:var(--bg);box-shadow:0 8px 24px rgba(0,0,0,0.06)}
.rs-menu-item{display:block;padding:9px 12px;font-size:14px;color:var(--text);letter-spacing:-.01em;border-bottom:1px solid var(--divider-subtle)}
.rs-menu-item:last-child{border-bottom:none}
.rs-menu-item.rs-menu-item-active,button.rs-menu-item-active{background:var(--divider-subtle)}
button.rs-menu-item{width:100%;text-align:left;cursor:pointer;background:none;border-left:none;border-right:none;border-top:none;font-family:inherit}

import * as React from "react";
import { cx } from "./cx";

export interface DialogProps extends Omit<React.DialogHTMLAttributes<HTMLDialogElement>, "open"> {
  open: boolean;
  onClose?: () => void;
}

/**
 * A native <dialog> — focus trapping, Escape, and the backdrop come
 * from the platform, not a dependency.
 */
export function Dialog({ open, onClose, className, children, ...props }: DialogProps) {
  const ref = React.useRef<HTMLDialogElement>(null);

  React.useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    else if (!open && dialog.open) dialog.close();
  }, [open]);

  return (
    <dialog ref={ref} className={cx("rs-dialog", className)} onClose={() => onClose?.()} {...props}>
      {children}
    </dialog>
  );
}

export function DialogTitle({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={cx("rs-dialog-title", className)} {...props} />;
}

export function DialogBody({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cx("rs-dialog-body", className)} {...props} />;
}

export function DialogActions({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cx("rs-dialog-actions", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Dialog — one question, two equal actions, no third option ── */
.rs-dialog{max-width:320px;border:1px solid var(--divider);border-radius:var(--radius);padding:20px;background:var(--bg);box-shadow:0 12px 32px rgba(0,0,0,0.08)}
dialog.rs-dialog{color:var(--text)}
dialog.rs-dialog::backdrop{background:rgba(0,0,0,0.25)}
.rs-dialog-title{display:block;font-size:15px;font-weight:600;letter-spacing:-.01em;color:var(--text);margin-bottom:6px}
.rs-dialog-body{font-size:13.5px;color:var(--text-secondary);letter-spacing:-.01em;line-height:1.55;margin:0 0 16px}
.rs-dialog-actions{display:flex;justify-content:flex-end;gap:8px}

import * as React from "react";
